import FloatNotifs from "./FloatNotifs.jsx";

// ── Constantes géométrie ──────────────────────────────────────────────────────
var D = 160, HWF = 0.895, HHF = 0.932, HLF = 0.052, HTF = 0.034;
var CSTEP = D * HWF, RSTEP = D * HHF * 0.75, OOFF = CSTEP * 0.5;
var PX = 5, PY = 5;

// ── Assets tuiles ─────────────────────────────────────────────────────────────
const T3 = "data:image/webp;base64,";
const T4 = "data:image/webp;base64,";
const T5 = "data:image/webp;base64,";
const T6 = "data:image/webp;base64,";
const T7 = "data:image/webp;base64,";

const TEMPLE1 = "data:image/webp;base64,";
const TEMPLE2 = "data:image/webp;base64,";


import {BANK_IMG, BARRACK_IMG, TOWER_IMG, CONSTR_TOWER, CONSTR_BARRACK, CONSTR_BANK} from "../../constant/assets.js";

const WARRIOR_IMGS = [
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,",
];

const COLORS = [
  { h: "#3B82F6" }, { h: "#EAB308" }, { h: "#EF4444" }, { h: "#22C55E" }
];

const TYPES = [
  { id: "ruins_flat",  img: T3 },
  { id: "ruins_cube",  img: T4 },
  { id: "ruins_wall",  img: T5 },
  { id: "ruins_stele", img: T6 },
  { id: "jungle",      img: T7 },
];

const TEMPLE_TYPES = [
  { id: "temple1", img: TEMPLE1 },
  { id: "temple2", img: TEMPLE2 },
];

// ── Helpers géométrie ─────────────────────────────────────────────────────────
function tileXY(id, cols) {
  var r = Math.floor(id / cols), c = id % cols;
  return { x: PX + c * CSTEP + (r % 2 === 1 ? OOFF : 0), y: PY + r * RSTEP };
}

function hexPolyXY(x, y) {
  var hl = x + D * HLF, hr = x + D * (1 - HLF), ht = y + D * HTF, hb = y + D * (HTF + HHF);
  var q1 = y + D * (HTF + HHF * 0.25), q3 = y + D * (HTF + HHF * 0.75), hc = x + D / 2;
  return hc.toFixed(1) + "," + ht.toFixed(1) + " " + hr.toFixed(1) + "," + q1.toFixed(1) + " " + hr.toFixed(1) + "," + q3.toFixed(1) + " " + hc.toFixed(1) + "," + hb.toFixed(1) + " " + hl.toFixed(1) + "," + q3.toFixed(1) + " " + hl.toFixed(1) + "," + q1.toFixed(1);
}

function hexCenterXY(x, y) {
  return { cx: x + D / 2, cy: y + D * (HTF + HHF * 0.5) };
}

// ── Cache type de tuile ───────────────────────────────────────────────────────
var _TTM = {};
export function resetTileTypeMap() { _TTM = {}; }

function getTileType(t) {
  if (_TTM[t.id] !== undefined) return _TTM[t.id];
  if (t.isDesert) { _TTM[t.id] = null; return null; }
  _TTM[t.id] = TYPES[t.id % TYPES.length];
  return _TTM[t.id];
}

// ── IsoTile ───────────────────────────────────────────────────────────────────
function IsoTile({ tile: t, cols, sel, sel2, isTr, pl, onS, hlIds }) {
  var pos = tileXY(t.id, cols), x = pos.x, y = pos.y;
  var poly = hexPolyXY(x, y), ctr = hexCenterXY(x, y), cx = ctr.cx, cy = ctr.cy;
  var ow = t.owner !== null && pl[t.owner] ? pl[t.owner] : null;
  var pc = ow ? ow.color : null;
  var isSel = sel === t.id, isSel2 = sel2 === t.id;
  var isHl = hlIds && hlIds.includes(t.id);
  var ttype = getTileType(t);

  if (t.isRemoved) return null;

  if (t.isDesert || !ttype) {
    var templeType = TEMPLE_TYPES[t.id % 2];
    var clipId = "tc" + t.id;
    return (
      <g onClick={function() { onS(t.id); }} style={{ cursor: "pointer", opacity: 0.85 }}>
        <defs><clipPath id={clipId}><polygon points={poly} /></clipPath></defs>
        <image href={templeType.img} x={x} y={y} width={D} height={D} preserveAspectRatio="xMidYMid meet" clipPath={"url(#" + clipId + ")"} />
        <polygon points={poly} fill="rgba(180,120,20,0.15)" stroke="rgba(200,160,40,0.5)" strokeWidth={1.5} strokeLinejoin="round" />
      </g>
    );
  }

  var hasWall     = (t.wall > 0) || (t.bType === "wall");
  var hasBank     = (t.bank > 0) || (t.bType === "bank");
  var hasBrk      = (t.barracks > 0) || (t.bType === "barracks");
  var wallImg     = t.wall > 0 ? TOWER_IMG : CONSTR_TOWER_IMG;
  var bankImg     = t.bank > 0 ? BANK_IMG  : CONSTR_BANK_IMG;
  var brkImg      = t.barracks > 0 ? BARRACK_IMG : CONSTR_BARRACK_IMG;
  var wImgHref    = t.owner !== null && ow
    ? WARRIOR_IMGS[Math.max(0, COLORS.findIndex(function(c) { return c.h === ow.color; })) + 1]
    : WARRIOR_IMGS[0];

  return (
    <g onClick={function() { onS(t.id); }} style={{ cursor: "pointer" }}>
      <image href={ttype.img} x={x} y={y} width={D} height={D} preserveAspectRatio="xMidYMid meet" />
      {pc && <polygon points={poly} fill="none" stroke={pc} opacity={0.22} />}
      {isSel && <polygon points={poly} fill="none" stroke="white" strokeWidth={3} strokeLinejoin="round" />}
      {isSel && <polygon points={poly} fill="none" stroke="white" strokeWidth="3" opacity=".5" filter="url(#gl)" strokeLinejoin="round" />}
      {isSel2 && !isSel && (isTr
        ? <polygon points={poly} fill="rgba(110,231,183,0.18)" stroke="#6EE7B7" strokeWidth={2.5} strokeLinejoin="round" />
        : <polygon points={poly} fill="none" stroke="#EF4444" strokeWidth={3} opacity=".4" filter="url(#gl)" strokeLinejoin="round" />
      )}
      {!isSel && !isSel2 && pc && <polygon points={poly} fill="none" stroke={pc} strokeWidth={3.25} opacity={0.9} />}
      {isHl && !isSel && <polygon points={poly} fill="rgba(255,255,255,0.32)" stroke="rgba(255,255,255,0.95)" strokeWidth={3} strokeLinejoin="round" strokeDasharray="5,3" />}

      {hasWall && <image href={wallImg} x={cx - D * 0.18} y={cy - D * 0.55} width={D * 0.36} height={D * 0.46} preserveAspectRatio="xMidYMid meet" />}
      {hasBank && <image href={bankImg} x={cx - D * 0.42} y={cy - D * 0.47} width={D * 0.375} height={D * 0.42} preserveAspectRatio="xMidYMid meet" />}
      {hasBrk  && <image href={brkImg}  x={cx + D * 0.04} y={cy - D * 0.44} width={D * 0.375} height={D * 0.375} preserveAspectRatio="xMidYMid meet" />}

      <text x={cx} y={cy - D * 0.05} textAnchor="middle" dominantBaseline="central"
        fontSize={D * 0.27} fontWeight="900" fill={pc || "white"} fontFamily="'Times New Roman',Georgia,serif"
        style={{ paintOrder: "stroke", stroke: "black", strokeWidth: D * 0.04, strokeLinejoin: "round" }}>
        {t.size}
      </text>
      <image href={wImgHref} x={cx - D * 0.208} y={cy + D * 0.05} width={D * 0.277} height={D * 0.307} preserveAspectRatio="xMidYMid meet" />
      <text x={cx + D * 0.10} y={cy + D * 0.20} textAnchor="middle" dominantBaseline="central"
        fontSize={D * 0.19} fontWeight="900" fill={pc || "white"} fontFamily="'Times New Roman',Georgia,serif"
        style={{ paintOrder: "stroke", stroke: "black", strokeWidth: D * 0.04, strokeLinejoin: "round" }}>
        {t.army}
      </text>
    </g>
  );
}

// ── GameBoard (GM) ─────────────────────────────────────────────────────────────
export default function GameBoard({ tiles: ti, players: ps, selected: se, selected2: se2, onSelect, hlIds, cols, rows, floatNotifs, trMode }) {
  var mCols = cols || 5;
  var mRows = Math.ceil(ti.length / mCols);
  var mw = PX + (mCols - 1) * CSTEP + OOFF + D + PX;
  var mh = PY + (mRows - 1) * RSTEP + D + PY;

  var sorted = [].concat(ti).sort(function(a, b) {
    if (a.isDesert !== b.isDesert) return a.isDesert ? -1 : 1;
    return Math.floor(a.id / mCols) - Math.floor(b.id / mCols) || a.id % mCols - b.id % mCols;
  });

  return (
    <svg viewBox={"0 0 " + Math.ceil(mw) + " " + Math.ceil(mh)} style={{ width: "100%", display: "block", borderRadius: 10 }}>
      <defs>
        <filter id="gl">
          <feGaussianBlur stdDeviation="3" result="b" />
          <feMerge><feMergeNode in="b" /><feMergeNode in="SourceGraphic" /></feMerge>
        </filter>
      </defs>
      <rect width="100%" height="100%" fill="rgba(255,255,255,0.40)" />

      {sorted.map(function(t) {
        return <IsoTile key={t.id} tile={t} cols={mCols} sel={se} sel2={se2} isTr={trMode} pl={ps} onS={onSelect} hlIds={hlIds || null} />;
      })}

      <FloatNotifs floatNotifs={floatNotifs} cols={mCols} />
    </svg>
  );
}
